 actions.wsFix=el=>task(async()=>{
  closeModal();if(el.dataset.task&&el.dataset.task!==api().activeId())await api().switchTask(el.dataset.task,'multiport');
  ui.home=false;ui.route=false;let view=el.dataset.view,record=null;const message=el.dataset.message||'';
  if(view==='stores')storeFilter='*';
  if(view==='voyage')voyageTab='details';
  if(view==='ports'){
   const ordinal=message.match(/第\s*(\d+)\s*(?:条|港)/);record=ordinal?portOutputSelection().rows[Number(ordinal[1])-1]:null;
   if(record){voyageTab=record._outputOrigin==='plan'?'plan':'history';view=voyageTab==='plan'?'plannedPorts':'ports';currentView='voyage'}
   else if(/没有可输出|表格为空/.test(message)){voyageTab='history';currentView='voyage';view='ports'}
   else currentView='ports';
  }else currentView=view;
  render();await new Promise(requestAnimationFrame);const root=$('#content [data-ws-editor]'),target=root&&issueTarget(view,message,root,record);
  if(target){const visible=target.hidden?target.closest('.choice-editor')?.querySelector('select')||target:target;for(let p=visible.parentElement;p;p=p.parentElement)if(p.tagName==='DETAILS')p.open=true;visible.focus({preventScroll:true});visible.scrollIntoView({block:'center',behavior:'smooth'});visible.classList.add('field-attention');setTimeout(()=>visible.classList.remove('field-attention'),2500)}
 });

 function reviewBody(){return review.report.reports.map(r=>{const t=api().inspect(r.id),keys=required(t),errors=r.results.flatMap(x=>x.errors.map(text=>({id:x.id,text}))),stale=(t.stale||[]);return `<section class="review-port" data-review-port="${esc(t.id)}"><div class="row spaced"><label class="checkline"><input type="checkbox" data-ws-review-port="${esc(t.id)}" ${review.selection.has(t.id)?'checked':''} ${review.onlyChanged&&r.unchanged?'disabled':''}><strong>${esc(r.label)}</strong></label><span class="badge ${r.pass?'ok':'warn'}">${r.pass?'可生成':'待核对'}</span></div><div class="review-confirmations">${keys.map(key=>`<label><input type="checkbox" data-ws-confirm="${key}" data-task="${esc(t.id)}" ${t.confirmed[key]?'checked':''}><span>${({dates:'已核对到离港日期',health:'已核对本港健康申报',nil:'已核对本港 NIL 申报'})[key]}</span></label>`).join('')}</div>${compactErrors(errors,t.id)}${stale.length?'<div class="note warn">资料发生变化，需要先处理。<button class="text-button" data-action="wsReviewResolve" data-id="'+esc(t.id)+'">打开此港核对</button></div>':''}${r.warnings.length?'<details><summary>'+r.warnings.length+' 项提醒</summary>'+r.warnings.map(text=>'<p>'+esc(text)+'</p>').join('')+'</details>':''}<div class="review-port-foot"><span>${r.outputs.length} 份文件</span><span>${r.baselineAt?(r.unchanged?'与上次生成一致':r.differences.length+' 项资料变化'):'首次生成'}</span></div>${r.differences.length?'<details><summary>查看与上次生成的变化</summary>'+diffTable(r.differences,100)+'</details>':''}</section>`}).join('')}
 function updateReview(){const root=$('#wsReviewBody');if(!root||!review)return;replaceReviewBody(root,reviewBody());const ids=review.report.reports.filter(r=>r.pass&&review.selection.has(r.id)&&(!review.onlyChanged||!r.unchanged)).map(r=>r.id),files=review.report.reports.filter(r=>ids.includes(r.id)).reduce((n,r)=>n+r.outputs.length,0),button=$('[data-action="wsConfirmGenerate"]');if(button){button.disabled=!ids.length;button.textContent=review.report.failed.some(id=>review.selection.has(id))?'仅生成勾选的已通过港口':'生成 '+ids.length+' 港 · '+files+' 份文件'}$('#wsReviewCount').textContent='可生成 '+ids.length+' 港 · '+files+' 份文件'}
 async function openReview(ids){if(!api().tasks().length)await api().create([],{includeCurrent:true});const explicit=!!ids;ids=ids||api().tasks().map(t=>t.id);if(!ids.length)throw Error('请在生成核对中选择要输出的港口。');const report=await MultiPortExport.check(ids);review={ids:[...ids],report,selection:new Set(explicit?ids:api().selectedIds()),onlyChanged:false};modal('生成前，一起核对',`<p class="muted">核对每港日期与申报，资料有变化时才需重新确认。未通过的港口继续保留。</p><div class="row spaced"><label class="checkline"><input type="checkbox" id="wsOnlyChanged">只更新有变化的港口</label><span id="wsReviewCount" class="muted"></span></div><div id="wsReviewBody"></div>`,`<button data-action="closeModal">继续填写</button><button class="primary" data-action="wsConfirmGenerate">生成文件</button>`);$('.dialog').classList.add('ws-review-dialog');updateReview()}
 actions.generateAll=()=>task(()=>openReview());actions.multiportGenerate=actions.generateAll;actions.mpCheckOne=el=>task(()=>openReview([el.dataset.id]));
 actions.wsReviewResolve=el=>task(async()=>{closeModal();await api().switchTask(el.dataset.id,'multiport');actions.wsResolve()});
 actions.wsConfirmGenerate=()=>task(async()=>{if(!review)return;const ids=review.report.reports.filter(r=>r.pass&&review.selection.has(r.id)&&(!review.onlyChanged||!r.unchanged)).map(r=>r.id);const result=await MultiPortExport.generate(ids,{reviewStamp:review.report.stamp});if(!result.success)throw Error('部分资料尚未通过，请重新核对。');review=null;closeModal();render()});

 const confirmText={dates:'已核对本港到离港日期',health:'已核对本港健康申报',nil:'已核对本港 NIL 申报'};
 function singleReviewBody(){const {report,fileId,taskId}=singleReview,r=report.reports[0],t=api().inspect(taskId),v=t.data.voyage,keys=['dates',...(fileId===6?['health']:[]),...(fileId===9?['nil']:[])],errors=r.results.flatMap(x=>x.errors.map(text=>({id:x.id,text})));return '<p class="single-file-context"><strong>'+esc(r.label)+'</strong><span>'+esc(v.arrivalDate||'到港日期未填')+' → '+esc(v.departureDate||'离港日期未填')+'</span></p><p class="hint">仅下载这份 XLSX，不改变本港 ZIP 的文件勾选。</p><div class="review-confirmations">'+keys.map(key=>'<label><input type="checkbox" data-single-confirm="'+key+'" data-task="'+esc(taskId)+'" '+(t.confirmed[key]?'checked':'')+'><span>'+confirmText[key]+'</span></label>').join('')+'</div>'+(!dateValue(v.arrivalDate)||!dateValue(v.departureDate)?'<p class="note warn">请先补齐有效的到离港日期。<button class="text-button" data-action="wsFix" data-view="voyage" data-task="'+esc(taskId)+'">填写靠港资料</button></p>':'')+compactErrors(errors,taskId)+(t.stale.length?'<p class="note warn">本港有上游资料变化，请核对后继续。<button class="text-button" data-action="wsReviewResolve" data-id="'+esc(taskId)+'">核对变化</button></p>':'')+(r.warnings.length?'<details><summary>'+r.warnings.length+' 项提醒</summary>'+r.warnings.map(text=>'<p>'+esc(text)+'</p>').join('')+'</details>':'')}
 function updateSingleReview(){const root=$('#singleFileReview');if(!root||!singleReview)return;replaceReviewBody(root,singleReviewBody());const button=$('[data-action=wsConfirmSingle]');if(button)button.disabled=!singleReview.report.reports[0].pass}
 async function openSingleReview(fileId){if(!Number.isInteger(fileId)||!documents.some(d=>d[3]===fileId))throw Error('请选择一份有效的文件。');ui.home=false;closeLibrary();const view=currentView;if(!api().tasks().length){await api().create([],{includeCurrent:true});currentView=view;render()}const taskId=api().activeId(),report=await MultiPortExport.checkSingle(taskId,fileId);if(report.reports[0].pass){const result=await MultiPortExport.generateSingle(taskId,fileId,{reviewStamp:report.stamp});if(!result.success)throw Error('资料已变化，请重新检查这份文件。');return result}singleReview={taskId,fileId,report};const title=documents.find(d=>d[3]===fileId)[1];modal('下载：'+title,'<div id="singleFileReview"></div>','<button data-action="closeModal">继续填写</button><button class="primary" data-action="wsConfirmSingle">核对后下载 XLSX</button>');$('.dialog').classList.add('single-file-dialog');updateSingleReview()}
 actions.wsDownloadFile=el=>task(()=>openSingleReview(Number(el.dataset.id)));actions.generateOne=actions.wsDownloadFile;
 actions.wsConfirmSingle=()=>task(async()=>{if(!singleReview)throw Error('请先检查这份文件。');const draft=singleReview,result=await MultiPortExport.generateSingle(draft.taskId,draft.fileId,{reviewStamp:draft.report.stamp});if(!result.success)throw Error('资料需要重新核对，本次未下载文件。');singleReview=null;closeModal()});
 actions.wsDocumentStep=el=>{const index=documents.findIndex(d=>d[0]===ui.page),next=documents[index+Number(el.dataset.step)];if(next)actions.wsGo({dataset:{view:next[0]}})};
 actions.wsSelectAllFiles=()=>{const t=active();if(!t)throw Error('请先准备本港。');api().transact(()=>{t.outputs=documents.map(d=>d[3]);t.status='draft'})};
 actions.wsGeneratePort=()=>task(()=>openReview(api().activeId()?[api().activeId()]:undefined));
 document.addEventListener('change',e=>{
  const el=e.target;
  if(el.hasAttribute('data-flow-document')){actions.wsGo({dataset:{view:el.value}});return}
  if(el.hasAttribute('data-flow-only-file')){const t=active(),id=Number(el.value);if(t&&documents.some(d=>d[3]===id))api().transact(()=>{t.outputs=[id];t.status='draft'});return}
  if(el.dataset.singleConfirm){const key=el.dataset.singleConfirm,value=el.checked;task(async()=>{await api().markConfirmed(singleReview.taskId,key,value);singleReview.report=await MultiPortExport.checkSingle(singleReview.taskId,singleReview.fileId);updateSingleReview()}).catch(()=>{});return}
  if(el.id==='mobilePageSelect'){actions.wsGo({dataset:{view:el.value}});return}
  if(el.dataset.wsSelect){const selected=new Set(api().selectedIds());el.checked?selected.add(el.dataset.wsSelect):selected.delete(el.dataset.wsSelect);api().select([...selected]);render()}
  if(el.hasAttribute('data-ws-select-all')){api().select(el.checked?api().tasks().map(t=>t.id):[]);render()}
  if(el.dataset.wsOutput){const id=Number(el.dataset.wsOutput),t=active();if(!t){toast('请先将当前港口加入准备列表，再选择输出文件。');el.checked=true;return}const outputs=new Set(t.outputs);el.checked?outputs.add(id):outputs.delete(id);if(!outputs.size){toast('至少保留一份文件。');el.checked=true;return}api().transact(()=>{t.outputs=[...outputs].sort((a,b)=>a-b);t.status='draft'});render()}
  if(el.dataset.wsConfirm){const id=el.dataset.task,key=el.dataset.wsConfirm,value=el.checked;task(async()=>{try{await api().markConfirmed(id,key,value)}catch(err){el.checked=!value;throw err}review.report=await MultiPortExport.check(review.ids);updateReview()}).catch(()=>{})}
  if(el.dataset.wsReviewPort){el.checked?review.selection.add(el.dataset.wsReviewPort):review.selection.delete(el.dataset.wsReviewPort);updateReview()}
  if(el.id==='wsOnlyChanged'){review.onlyChanged=el.checked;updateReview()}
 });
