 function decorateStockDialog(){const rates=$('#modalRoot [data-route-section="rates"]'),table=rates?.querySelector('table');if(!table||rates.querySelector('[data-route-section="otherRates"]'))return;const rows=[...table.tBodies[0].rows].filter(row=>row.querySelector('[data-route-stock-rate="dailyRates"]'));if(!rows.length)return;const d=document.createElement('details');d.dataset.routeSection='otherRates';d.open=otherRatesOpen;d.className='inline-advanced';d.innerHTML='<summary>其他物料每日耗用（可选）</summary><div class="tablewrap"><table><thead>'+table.tHead.innerHTML+'</thead><tbody></tbody></table></div>';rates.append(d);rows.forEach(row=>d.querySelector('tbody').append(row));if(!table.tBodies[0].rows.length)table.closest('.tablewrap').hidden=true}
