 function updateDock(){const view=ui.section==='workspace'?ui.page:currentView;for(const el of $$('.dock-item')){const on=!ui.home&&(el.dataset.view?el.dataset.view===view:el.dataset.group==='documents'?documents.some(d=>d[0]===view):['library','defaults','records','settings'].includes(ui.section));el.classList.toggle('active',on);if(on)el.setAttribute('aria-current','true');else el.removeAttribute('aria-current')}$('#content').classList.toggle('is-home',!!$('#content .ws-welcome'))}
